Q: How to get longest sequences of equal characters and how many are they if more than one? A: <p>ALL the credit here goes to the OTHER answer here. <a href="https://stackoverflow.com/a/52152057/125981">https://stackoverflow.com/a/52152057/125981</a>  I merely adapted it to return results against an array of values.  Please up-vote/accept that one perhaps.</p>

<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>var sequences = ['11ADD', '115222', 'ABCDEF10'];

function getLongestSeqList(input) {
  return input
    .match(/(.)\1*/g)
    .sort((a, b) =&gt; b.length - a.length)
    .filter((a, i, arr) =&gt; a.length === arr[0].length)
}

function getValues(s) {
  let seq = getLongestSeqList(s);
  return {
    Count: seq.length,
    Len: seq[0].length
  };
}
sequences.forEach(function(s) {
  console.log(getValues(s));
});</code></pre>
</div>
</div>
